def md(intro, feats, who, hf, hw):
    return intro + "\n\n### " + hf + "\n\n" + "\n".join("- " + f for f in feats) + "\n\n### " + hw + "\n\n" + who
f = '_data/catalogo.json'
d = json.load(io.open(f, encoding='utf-8'))
m = {x[0]: x for x in D}
for p in d['prodotti']:
    x = m.get(p['id'])
    if not x: continue
    p['descrizione'] = x[1]
    p['descrizione_completa'] = md(x[2], x[3], x[4], "Cosa puoi fare", "Per chi è")
    p.setdefault('tr', {}).setdefault('en', {})
    p['tr']['en']['nome'] = p['nome']
    p['tr']['en']['descrizione'] = x[5]
    p['tr']['en']['descrizione_completa'] = md(x[6], x[7], x[8], "What you can do", "Who it's for")
io.open(f, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=2))
print('ok', len(m))
